      "path": "packages/plugin-daily-log/src/index.ts",
      "content": "/**\n * @zzerx/dsh-plugin-daily-log —— host 入口。\n * 打开 daily-log 域 → 提供 ctx.dailyLog 服务（client 经 Typert remote 直连）→\n * 注册设置命名空间 → 装配内置渠道（git/claude/codex/dsh）→ 读取 DSH 工作区项目候选。\n *\n * DSH 会话渠道（sources/dsh.ts）直接读 <DSH_HOME>/sessions 下的会话文件：\n * 按会话头部 cwd 归属项目，正文为追加写的多帧 zstd，须逐帧解压。\n *\n * agent 侧按需注入：15 个 daily_log_* 工具与详细引导段默认不注册 ——\n * 常态只挂一个常驻派发器工具 daily_log 与一句短指针；模型经 daily_log 工具或\n * 用户敲 /report 触发 gate.enable(agent)，才把整组工具 + 详细段注入该 agent scope。\n */\n\nimport { Context } from '@deepseek-ai/cordis'\nimport { dailyLogDomain } from './domain.ts'\nimport { DailyLogService } from './service.ts'\nimport { configureDailyLogSettingsPage, dailyLogConfigOf, installDailyLogSettings, type Config } from './settings.ts'\nimport type { DailyLogSettingsAccess } from './settings.ts'\nimport { builtinChannels } from './sources/index.ts'\nimport { buildDailyLogTools, installDailyLogTools } from './agent/tools.ts'\nimport { createToolGate } from './agent/tool-gate.ts'\nimport type { ToolGate } from './agent/tool-gate.ts'\nimport { installDailyLogPointerPrompt, registerDailyLogGuidance } from './agent/reference.ts'\nimport { installReportCommand } from './agent/command-report.ts'\n\nexport const name = '@zzerx/dsh-plugin-daily-log'\nexport const inject = ['storageDomain']\n/** 插件配置 schema（settings 分区的命名空间就是本条目 id，见 settings.ts）。 */\nexport { Config } from './settings.ts'\n\n/** workspaceRegistry（dsh-workspace）的最小视图，仅取候选发现所需字段。 */\ninterface WorkspaceRegistryLike {\n  list(): Array<{ path: string; title: string; sessionIds: readonly unknown[] }>\n}\n\n/**\n * 读取 DSH 工作区已添加项目（ctx.workspaceRegistry 同步投影）。\n * registry 未装配（web profile 缺 dsh-web-app 等）或读取异常一律返回 []，\n * 由 service 端优雅降级为「无工作区候选」。\n */\nasync function readWorkspaceProjects(\n  ctx: Context,\n): Promise<Array<{ path: string; title?: string; sessionIds: readonly string[] }>> {\n  const registry = (ctx as unknown as { get(name: string): WorkspaceRegistryLike | undefined }).get('workspaceRegistry')\n  if (!registry || typeof registry.list !== 'function') return []\n  try {\n    return registry\n      .list()\n      .map((w) => ({ path: w.path, title: w.title, sessionIds: w.sessionIds.map((x) => String(x)) }))\n  } catch {\n    return []\n  }\n}\n\nexport async function apply(ctx: Context, config: Config): Promise<void> {\n  const domain = await ctx.storageDomain.open(dailyLogDomain)\n  try {\n    ctx.effect(() => () => { void domain.close() })\n    // 用 new（而非 ctx.plugin）：把 dailyLog 服务 provide 在本 apply 的 fiber 上，\n    // 后续 ctx.inject(['tools'], ...) 子 fiber 才能沿祖先链读到 ctx.dailyLog。\n    new DailyLogService(ctx, {\n      domain,\n      channels: builtinChannels,\n      // 数据源页「DSH 工作区」组的候选来源（含每项目的 sessionIds，供 dsh 会话渠道）。\n      workspaceProjects: () => readWorkspaceProjects(ctx),\n      // 配置每次现取（volatile 引用值随设置热更新，不重挂插件）。\n      readPreferences: () => dailyLogConfigOf(config),\n    })\n    // settings 句柄要交给 /report 指令（开关联动其注册与否），不再丢弃返回值。\n    const settings = installDailyLogSettings(ctx, config)\n    installDailyLogAgentBridgeWhenReady(ctx, settings)\n    // 本插件自带设置页面（settings.section），关掉宿主按 schema 自建页面的策略。\n    configureDailyLogSettingsPage(ctx)\n  } catch (error) {\n    void domain.close()\n    throw error\n  }\n}\n\n/** 建 gate：一次 enable 同时注入 15 个工具 + 详细引导段。 */\nexport function createDailyLogGate(ctx: Context): ToolGate {\n  return createToolGate((scope) => {\n    const disposers: Array<() => void> = []\n    buildDailyLogTools(ctx.dailyLog, (definition) => {\n      disposers.push(scope.tools.register(definition))\n    })\n    disposers.push(registerDailyLogGuidance(scope))\n    return () => { for (const d of disposers.reverse()) d() }\n  })\n}\n\n/**\n * agent 桥可选增强：tools 服务注册后挂常驻派发器（+ guard / pre-execute 钩子），\n * systemPrompt 注册后挂常驻短指针；/report 指令交给 settings 开关联动。\n * 任何一步抛错只降级桥本身，不拖垮核心服务。\n */\nexport function installDailyLogAgentBridgeWhenReady(ctx: Context, settings: DailyLogSettingsAccess): void {\n  const gate = createDailyLogGate(ctx)\n  ctx.effect(() => () => gate.dispose())\n  // tools 与 systemPrompt 仍分开 inject：任一缺失只降级该部分（沿用原有容错姿态）。\n  void ctx.inject(['tools'], (toolsCtx) => {\n    try {\n      installDailyLogTools(toolsCtx, gate)\n    } catch (error) {\n      toolsCtx.logger.error('[plugin-daily-log] agent tools install failed — daily_log_* unavailable to sessions:', error)\n    }\n  })\n  void ctx.inject(['systemPrompt'], (promptCtx) => {\n    try {\n      installDailyLogPointerPrompt(promptCtx)\n    } catch (error) {\n      promptCtx.logger.error('[plugin-daily-log] pointer prompt install failed:', error)\n    }\n  })\n  installReportCommand(ctx, gate, settings)\n}\n"
    },
    {
      "path": "packages/plugin-daily-log/src/service.ts",
      "content": "/**\n * ctx.dailyLog：项目（数据源）/报告/模板 CRUD + 按项目聚合多渠道扫描。\n * 数据源 = 一个项目路径；git/dsh/claude/codex 是渠道，命中者全部聚合。\n * 活动统一归属项目名；读取走内存态，写入持久化后生效。\n */\n\nimport { randomUUID } from 'node:crypto'\nimport { mkdir, writeFile } from 'node:fs/promises'\nimport { homedir } from 'node:os'\nimport { join } from 'node:path'\nimport { TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { brandString } from '@deepseek-ai/dsh-brand'\nimport type { Domain, KvTable } from '@deepseek-ai/dsh-storage-domain'\nimport type { dailyLogDomain } from './domain.ts'\nimport type { ChannelProvider } from './sources/provider.ts'\nimport { detectProjectType } from './sources/detect.ts'\nimport { discoverSessionProjects } from './sources/discover.ts'\nimport { BUILTIN_TEMPLATE } from './types.ts'\nimport type {\n  ActivityEntry, DateRange, ProjectCandidate, ProjectChannels, ReportCreateInput,\n  ReportId, ReportPrepareInput, ReportPrepareResult, ReportRecord,\n  ReportSaveInput, ScanResult, SourceAddInput, SourceId, SourceRecord, TemplateId,\n  TemplateRecord,\n} from './types.ts'\nimport { DEFAULT_TEMPLATE_SKELETON, formatDateRange, parseTemplate } from './template.ts'\n\nexport interface DailyLogServiceConfig {\n  readonly domain: Domain<typeof dailyLogDomain>\n  /** dsh 渠道由 host 装配。 */\n  readonly channels?: readonly ChannelProvider[]\n  readonly workspaceProjects?: () => Promise<Array<{ path: string; title?: string; sessionIds: readonly string[] }>>\n  readonly readPreferences?: () => { readonly outputDir?: string; readonly authorEmail?: string }\n}\n\nexport function normalizePathKey(p: string): string {\n  return p.trim().replace(/[\\\\/]+$/, '').replace(/\\\\/g, '/').toLowerCase()\n}\n\nfunction defaultSourceLabel(path: string): string {\n  return path.split(/[\\\\/]/).filter(Boolean).pop() ?? path\n}\n\nfunction errText(e: unknown): string {\n  if (e instanceof Error) return e.message\n  return String(e)\n}\n\nexport class DailyLogService extends TypertRemoteService {\n  private readonly sources: KvTable<SourceId, SourceRecord>\n  private readonly reports: KvTable<ReportId, ReportRecord>\n  private readonly templates: KvTable<TemplateId, TemplateRecord>\n  private readonly channels: readonly ChannelProvider[]\n  private readonly config: DailyLogServiceConfig\n  private migrated = false\n  private migrationPromise: Promise<void> | null = null\n\n  constructor(ctx: Context, config: DailyLogServiceConfig) {\n    super(ctx, 'dailyLog')\n    this.config = config\n    this.sources = config.domain.table('sources')\n    this.reports = config.domain.table('reports')\n    this.templates = config.domain.table('templates')\n    this.channels = config.channels ?? []\n    // put 的同步段先写内存态，异步段持久化，故此处 void。\n    const now = Date.now()\n    const builtin = Array.from(this.templates.entries(), ([, t]) => t).find((t) => t.isBuiltin)\n    if (!builtin) {\n      const seed: TemplateRecord = {\n        id: brandString<TemplateId>(randomUUID()),\n        name: BUILTIN_TEMPLATE,\n        content: DEFAULT_TEMPLATE_SKELETON,\n        isBuiltin: true,\n        isDefault: true,\n        updatedAt: now,\n      }\n      void this.templates.put(seed.id, seed)\n    } else if (builtin.content.includes('{{')) {\n      void this.templates.put(builtin.id, { ...builtin, content: DEFAULT_TEMPLATE_SKELETON, updatedAt: now })\n    }\n  }\n\n  private ensureMigrated(): Promise<void> {\n    if (this.migrated) return Promise.resolve()\n    this.migrationPromise ??= this.runLegacyMigration()\n    return this.migrationPromise\n  }\n\n  /**\n   * 旧记录迁移：kind=git 转项目记录，其余（会话目录）丢弃——内容可从渠道重取。\n   * 仅处理仍带 kind 的记录，故幂等。\n   */\n  private async runLegacyMigration(): Promise<void> {\n    const legacy: Array<{ id: SourceId; record: SourceRecord & { kind?: unknown } }> = []\n    for (const [id, s] of this.sources.entries()) {\n      const kind = (s as { kind?: unknown }).kind\n      if (typeof kind === 'string') legacy.push({ id, record: s })\n    }\n    if (legacy.length === 0) {\n      this.migrated = true\n      return\n    }\n    for (const { id, record } of legacy) {\n      if (record.kind !== 'git') {\n        await this.sources.delete(id)\n        continue\n      }\n      const clean: SourceRecord = {\n        id: record.id,\n        type: record.type ?? (await detectProjectType(record.path)),\n        label: record.label,\n        path: record.path,\n        ...(record.author !== undefined ? { author: record.author } : {}),\n        createdAt: record.createdAt,\n        updatedAt: record.updatedAt,\n      }\n      await this.sources.put(id, clean)\n    }\n    this.migrated = true\n  }\n\n  async listSources(): Promise<SourceRecord[]> {\n    await this.ensureMigrated()\n    return Array.from(this.sources.entries(), ([, s]) => s)\n  }\n\n  async addSource(input: SourceAddInput): Promise<SourceRecord> {\n    await this.ensureMigrated()\n    const path = input.path.trim()\n    if (!path) throw new Error('路径不能为空')\n    if (Array.from(this.sources.entries(), ([, s]) => s).some((s) => normalizePathKey(s.path) === normalizePathKey(path))) {\n      throw new Error('该项目已在数据源中')\n    }\n    const now = Date.now()\n    const record: SourceRecord = {\n      id: brandString<SourceId>(randomUUID()),\n      type: input.type ?? (await detectProjectType(path)),\n      label: input.label?.trim() || defaultSourceLabel(path),\n      path,\n      ...(input.author !== undefined && input.author !== '' ? { author: input.author.trim() } : {}),\n      createdAt: now,\n      updatedAt: now,\n    }\n    await this.sources.put(record.id, record)\n    return record\n  }\n\n  async removeSource(id: SourceId): Promise<boolean> {\n    await this.ensureMigrated()\n    return this.sources.delete(id)\n  }\n\n  private async probeChannels(path: string): Promise<ProjectChannels> {\n    const out: ProjectChannels = { git: false, dsh: false, claude: false, codex: false }\n    for (const ch of this.channels) {\n      try {\n        if (await ch.probe(path)) out[ch.kind] = true\n      } catch {\n        // 渠道探测失败视为未命中\n      }\n    }\n    return out\n  }\n\n  private hasSourcePath(path: string): boolean {\n    const key = normalizePathKey(path)\n    return Array.from(this.sources.entries(), ([, s]) => s).some((s) => normalizePathKey(s.path) === key)\n  }\n\n  async listWorkspaceCandidates(): Promise<ProjectCandidate[]> {\n    await this.ensureMigrated()\n    const projects = (await this.config.workspaceProjects?.()) ?? []\n    const out: ProjectCandidate[] = []\n    for (const p of projects) {\n      const channels = await this.probeChannels(p.path)\n      // dsh 渠道未接入，故徽标恒为暗。\n      out.push({\n        path: p.path,\n        title: p.title || defaultSourceLabel(p.path),\n        type: await detectProjectType(p.path),\n        channels,\n        detail: p.sessionIds.length > 0 ? p.sessionIds.length + ' 个 DSH 会话（DSH 源未接入）' : undefined,\n        added: this.hasSourcePath(p.path),\n      })\n    }\n    return out\n  }\n\n  async discoverSessionProjects(): Promise<ProjectCandidate[]> {\n    await this.ensureMigrated()\n    const found = await discoverSessionProjects()\n    const out: ProjectCandidate[] = []\n    for (const f of found) {\n      const channels: ProjectChannels = { git: false, dsh: false, claude: f.claude, codex: f.codex }\n      out.push({\n        path: f.path,\n        title: defaultSourceLabel(f.path),\n        type: await detectProjectType(f.path),\n        channels,\n        detail: f.sessionCount > 0 ? `${f.sessionCount} 个会话` : undefined,\n        added: this.hasSourcePath(f.path),\n      })\n    }\n    return out\n  }\n\n  /** 单渠道异常不中断整体，错误汇入 truncatedHint。 */\n  async scanSource(id: SourceId, range: DateRange): Promise<ScanResult> {\n    await this.ensureMigrated()\n    const source = this.sources.get(id)\n    if (!source) throw new Error(`source ${id} not found`)\n    const entries: ActivityEntry[] = []\n    const errors: string[] = []\n    for (const ch of this.channels) {\n      let hit = false\n      try {\n        hit = await ch.probe(source.path)\n      } catch {\n        hit = false\n      }\n      if (!hit) continue\n      try {\n        const author = this.resolveGitAuthor(source)\n        const got = await ch.scan({\n          path: source.path,\n          label: source.label,\n          range,\n          ...(author !== undefined ? { author } : {}),\n        })\n        entries.push(...got.map((e) => ({ ...e, sourceLabel: source.label, channel: ch.kind })))\n      } catch (e) {\n        errors.push(`[${ch.kind}] ${errText(e)}`)\n      }\n    }\n    return {\n      sourceId: id,\n      entries,\n      truncated: errors.length > 0,\n      ...(errors.length > 0 ? { truncatedHint: errors.join('；') } : {}),\n    }\n  }\n\n  listReports(): ReportRecord[] {\n    return Array.from(this.reports.entries(), ([, r]) => r)\n  }\n\n  getReport(id: ReportId): ReportRecord | undefined {\n    return this.reports.get(id)\n  }\n\n  async createReport(input: ReportCreateInput): Promise<ReportRecord> {\n    const now = Date.now()\n    const record: ReportRecord = {\n      id: brandString<ReportId>(randomUUID()),\n      title: input.title,\n      markdown: input.markdown,\n      sourceIds: input.sourceIds,\n      ...(input.templateId !== undefined ? { templateId: input.templateId } : {}),\n      ...(input.reportType !== undefined ? { reportType: input.reportType } : {}),\n      dateRange: input.dateRange,\n      createdAt: now,\n    }\n    await this.reports.put(record.id, record)\n    return record\n  }\n\n  async deleteReport(id: ReportId): Promise<boolean> {\n    return this.reports.delete(id)\n  }\n\n  private resolveTemplate(templateId?: TemplateId): TemplateRecord | undefined {\n    if (templateId !== undefined) return this.templates.get(templateId)\n    return this.listTemplates().find((t) => t.isDefault) ?? this.listTemplates().find((t) => t.isBuiltin)\n  }\n\n  /** 只解析模板，不扫描；scan 结果由 agent 侧提供。 */\n  async prepareReport(input: ReportPrepareInput): Promise<ReportPrepareResult> {\n    const ids = input.sourceIds ?? Array.from(this.sources.entries(), ([, s]) => s.id)\n    const template = this.resolveTemplate(input.templateId)\n    const parts = parseTemplate(template?.content ?? DEFAULT_TEMPLATE_SKELETON)\n    return {\n      reportType: input.reportType,\n      dateRange: input.dateRange,\n      sourceIds: ids,\n      sourceCount: ids.length,\n      template: {\n        name: template?.name ?? BUILTIN_TEMPLATE,\n        ...(parts.promptSection !== null ? { promptSection: parts.promptSection } : {}),\n        skeletonSection: parts.skeletonSection,\n      },\n    }\n  }\n\n  async saveReport(input: ReportSaveInput): Promise<ReportRecord> {\n    const markdown = input.markdown.trim()\n    if (!markdown) throw new Error('报告正文不能为空')\n    return this.createReport({\n      title: input.title?.trim() || (input.reportType ?? '报告') + ' · ' + formatDateRange(input.dateRange),\n      markdown,\n      sourceIds: input.sourceIds,\n      ...(input.templateId !== undefined ? { templateId: input.templateId } : {}),\n      ...(input.reportType !== undefined ? { reportType: input.reportType } : {}),\n      dateRange: input.dateRange,\n    })\n  }\n\n  /** 返回导出文件的绝对路径。 */\n  async exportReport(id: ReportId, outputDir?: string): Promise<string> {\n    const report = this.reports.get(id)\n    if (!report) throw new Error('report ' + id + ' not found')\n    const dir = outputDir?.trim() || this.configuredOutputDir() || join(homedir(), 'daily-log-reports')\n    await mkdir(dir, { recursive: true })\n    const safe = report.title.replace(/[\\\\/:*?\"<>|]/g, '-').trim() || 'report'\n    const filePath = join(dir, safe + '.md')\n    await writeFile(filePath, report.markdown, 'utf8')\n    return filePath\n  }\n\n  /** 未配置或读取抛错时为空串。 */\n  private configuredOutputDir(): string {\n    try {\n      const value = this.config.readPreferences?.()?.outputDir\n      return typeof value === 'string' ? value.trim() : ''\n    } catch {\n      return ''\n    }\n  }\n\n  /** 未配置或读取抛错时为空串。 */\n  private configuredAuthorEmail(): string {\n    try {\n      const value = this.config.readPreferences?.()?.authorEmail\n      return typeof value === 'string' ? value.trim() : ''\n    } catch {\n      return ''\n    }\n  }\n\n  /**\n   * 返回 undefined 时由 git 渠道回落仓库 user.email。\n   * `*` / `all` 由渠道解释为放开全作者。\n   */\n  private resolveGitAuthor(source: SourceRecord): string | undefined {\n    const explicit = source.author?.trim()\n    if (explicit) return explicit\n    return this.configuredAuthorEmail() || undefined\n  }\n\n  listTemplates(): TemplateRecord[] {\n    return Array.from(this.templates.entries(), ([, t]) => t)\n  }\n\n  getTemplate(id: TemplateId): TemplateRecord | undefined {\n    return this.templates.get(id)\n  }\n\n  async createTemplate(input: { name: string; content: string }): Promise<TemplateRecord> {\n    const name = input.name.trim()\n    if (!name) throw new Error('模板名不能为空')\n    if (name === BUILTIN_TEMPLATE) throw new Error(`\"${BUILTIN_TEMPLATE}\" 是内置模板，不可创建`)\n    if (Array.from(this.templates.entries(), ([, t]) => t).some((t) => t.name === name)) {\n      throw new Error(`模板 \"${name}\" 已存在`)\n    }\n    const now = Date.now()\n    const record: TemplateRecord = {\n      id: brandString<TemplateId>(randomUUID()),\n      name,\n      content: input.content,\n      isBuiltin: false,\n      isDefault: false,\n      updatedAt: now,\n    }\n    await this.templates.put(record.id, record)\n    return record\n  }\n\n  async updateTemplate(\n    id: TemplateId,\n    patch: { name?: string; content?: string },\n  ): Promise<TemplateRecord | undefined> {\n    const current = this.templates.get(id)\n    if (!current) return undefined\n    if (current.isBuiltin) throw new Error('内置模板不可更新')\n    const now = Date.now()\n    let name = current.name\n    if (patch.name !== undefined) {\n      name = patch.name.trim()\n      if (!name) throw new Error('模板名不能为空')\n      if (name === BUILTIN_TEMPLATE) throw new Error(`\"${BUILTIN_TEMPLATE}\" 是内置模板，不可使用`)\n      if (name !== current.name && Array.from(this.templates.entries(), ([, t]) => t).some((t) => t.id !== id && t.name === name)) {\n        throw new Error(`模板 \"${name}\" 已存在`)\n      }\n    }\n    const next: TemplateRecord = {\n      ...current,\n      name,\n      ...(patch.content !== undefined ? { content: patch.content } : {}),\n      updatedAt: now,\n    }\n    await this.templates.put(id, next)\n    return next\n  }\n\n  async deleteTemplate(id: TemplateId): Promise<boolean> {\n    const current = this.templates.get(id)\n    if (!current) return false\n    if (current.isBuiltin) throw new Error('内置模板不可删除')\n    return this.templates.delete(id)\n  }\n\n  async setDefaultTemplate(id: TemplateId): Promise<boolean> {\n    const target = this.templates.get(id)\n    if (!target) return false\n    const now = Date.now()\n    for (const [tid, t] of this.templates.entries()) {\n      if (t.isDefault && tid !== id) {\n        await this.templates.put(tid, { ...t, isDefault: false, updatedAt: now })\n      }\n    }\n    await this.templates.put(id, { ...target, isDefault: true, updatedAt: now })\n    return true\n  }\n}\n\n/**\n * 手工复刻 @Remote 装饰器产物，避免构建依赖标准装饰器转译。\n * 下方 method 名必须与 client 端 descriptors 完全一致。\n */\nconst REMOTE_METHODS = '@deepseek-ai/dsh-typert-protocol/remote-methods'\n\nfunction markRemoteMethods(prototype: object, methods: readonly string[]): void {\n  Object.defineProperty(prototype, REMOTE_METHODS, {\n    configurable: true,\n    value: Object.freeze({\n      version: 1,\n      methods: Object.freeze(\n        methods.map((method) =>\n          Object.freeze({ method, invocation: Object.freeze({ kind: 'direct' as const }) }),\n        ),\n      ),\n    }),\n  })\n}\n\nmarkRemoteMethods(DailyLogService.prototype, [\n  'listSources',\n  'addSource',\n  'removeSource',\n  'scanSource',\n  'listWorkspaceCandidates',\n  'discoverSessionProjects',\n  'listReports',\n  'getReport',\n  'deleteReport',\n  'exportReport',\n  'listTemplates',\n  'getTemplate',\n  'createTemplate',\n  'updateTemplate',\n  'deleteTemplate',\n  'setDefaultTemplate',\n])\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    dailyLog: DailyLogService\n  }\n}\n"
    },
    {
      "path": "packages/plugin-daily-log/src/agent/reference.ts",
      "content": "/**\n * plugin-daily-log × agent harness 桥（host 侧）—— 对话式生成报告的模型引导。\n * 三段软性约束：总则 / 收集礼仪 / 生成礼仪（无阶段状态机，靠提示 + 工具条件）。\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { AgentScopeContext } from './tool-gate.ts'\n\nexport const DAILY_LOG_REFERENCE_SECTION = 'forge-daily-log:reporting'\n\n/** 可测试的提示文本常量。 */\nexport const DAILY_LOG_REFERENCE_TEXT = [\n  '## Daily work log (plugin-daily-log)',\n  '',\n  'Generate daily/weekly/monthly work reports conversationally from Git commits and local agent conversations',\n  '(deepseek / claude / codex) via the daily_log_* tools.',\n  '',\n  '### 总则',\n  '- data-driven：一切结论必须来自 daily_log_* 工具返回的真实数据，绝不编造或推测。',\n  '- 诚实透明：空数据、工具失败如实告知，不用默认值掩盖。',\n  '- 中文交流；报告用业务语言，不用代码流水账。',\n  '',\n  '### 收集（扫描前）',\n  '- 先确认时间范围与项目集（daily_log_list_sources 查看已添加项目）；用户指令不完整时反问，不自行猜测。',\n  '- 扫描结果为空/明显过少、提交信息过简（update/fix/wip 之类）→ 反问是否遗漏项目或范围有误。',\n  '- 扫描后口头询问「是否有未提交/未完成/未体现在扫描结果里的工作（协助、会议、进行中会话等）」。',\n  '',\n  '### 生成（撰写正文）',\n  '- 调用 daily_log_prepare_report 获取所选模板的指令/骨架引导，然后【你亲自撰写正文】。',\n  '- 按骨架归类：feat/新增 → 核心产出；fix → 问题修复；refactor/perf → 技术优化；隐性工作 → 其他工作。',\n  '- 同功能多次提交合并为一条业务描述。坏例：「修改了 user.ts 的 login 方法」；好例：「完成用户登录模块重构，提升可维护性」。',\n  '- 写完先在回复中展示正文并询问是否调整；用户要求调整则按意见修改正文，改完再次询问；未经用户确认不得调用 daily_log_save_report / daily_log_export_report。',\n].join('\\n')\n\nexport const DAILY_LOG_POINTER_SECTION = 'forge-daily-log:reporting-entry'\nexport const DAILY_LOG_POINTER_ORDER = 2949\n\n/** 常驻短指针：只说「按需启用」与触发方式，不点名任何具体工具。 */\nexport const DAILY_LOG_POINTER_TEXT = [\n  '## 工作报告能力（plugin-daily-log）· 按需启用',\n  '',\n  '这项能力默认不加载，以免占用日常上下文。当用户要求生成日报 / 周报 / 月报、汇报「这段时间做了什么」、',\n  '统计提交或整理工作内容时，先调用 daily_log 工具启用。',\n  '启用后本轮即可使用全部工作报告工具，并会附带详细的工作流引导。',\n].join('\\n')\n\n/**\n * 把详细引导注册进 agent scope —— 真机上这条路**不生效**：agent 作用域提供 `tools`\n * （所以 15 个工具确实能注入），但不提供 `systemPrompt`，本函数首行即短路返回，整段引导被静默丢弃\n * （2026-09-15 真机验收：对引导一无所知的探针 agent 被问「系统提示词是否禁止未经确认调用某些工具」，\n * 答案是 NONE；用户侧表现为模型直接开扫）。\n *\n * 保留它只为仍装配 systemPrompt 的宿主；**权威投递路径是对话本身** ——\n * tool-dispatcher.ts 的启用结果与 command-report.ts 的续接消息各自携带全文。\n * 不要把这里当兜底：模型能否读到引导，取决于那两处。\n */\nexport function registerDailyLogGuidance(scope: AgentScopeContext): () => void {\n  if (scope.systemPrompt === undefined) return () => {}\n  return scope.systemPrompt.section({\n    name: DAILY_LOG_REFERENCE_SECTION,\n    order: 2950,\n    text: DAILY_LOG_REFERENCE_TEXT,\n  })\n}\n\n/** 常驻短指针（全局，每轮都在；指针本身不含具体工具名）。 */\nexport function installDailyLogPointerPrompt(ctx: Context): void {\n  ctx.systemPrompt.section({\n    name: DAILY_LOG_POINTER_SECTION,\n    order: DAILY_LOG_POINTER_ORDER,\n    text: DAILY_LOG_POINTER_TEXT,\n  })\n}\n"
    },
    {
      "path": "packages/plugin-daily-log/src/agent/tool-gate.ts",
      "content": "/**\n * 按 agent scope 注册一组 agent 侧贡献（工具 / systemPrompt 段），幂等。\n *\n * 工具与 prompt 段的可见性都是按 scope 现算的（ToolRuntime.register 明说\n * 'Register globally or in the calling agent scope'，SystemPrompt 是 Scoped 服务），\n * 因此「用到时才注入」= 拿到 agent 的 scope ctx 后注册。公开类型 Agent 只有 { id }，\n * scope ctx 属于宿主运行时增广 —— 用窄接口读取，集中在 agentScopeOf 一处。\n */\n\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type { ToolDefinition } from '@deepseek-ai/dsh-tools'\n\n/** agent scope ctx 的最小视图：tools 必需，systemPrompt 可缺（宿主可能未装配）。 */\nexport interface AgentScopeContext {\n  readonly tools: {\n    register(definition: ToolDefinition): () => void\n  }\n  readonly systemPrompt?: {\n    section(section: { name: string; order: number; text: string }): () => void\n  }\n}\n\n/** 读 agent 的 scope ctx；宿主未暴露时抛错（由调用方转成面向模型的错误文本）。 */\nexport function agentScopeOf(agent: Agent): AgentScopeContext {\n  const scope = (agent as unknown as { ctx?: AgentScopeContext }).ctx\n  if (scope === undefined || scope.tools === undefined) {\n    throw new Error('[plugin-daily-log] agent scope context is unavailable (agent.ctx)')\n  }\n  return scope\n}\n\n/** 一次 enable 要建立的全部注册；返回的 disposer 释放它们。 */\nexport type GateContribution = (scope: AgentScopeContext) => () => void\n\nexport interface ToolGate {\n  /** 幂等启用；已启用或 gate 已关闭返回 false。 */\n  enable(agent: Agent): boolean\n  isEnabled(agent: Agent): boolean\n  /** 释放全部注册并关闭 gate（插件卸载与测试用）。 */\n  dispose(): void\n}\n\nexport function createToolGate(contribution: GateContribution): ToolGate {\n  const installed = new WeakMap<Agent, () => void>()\n  const all = new Set<() => void>()\n  let closed = false\n  return {\n    enable(agent) {\n      if (closed || installed.has(agent)) return false\n      const release = contribution(agentScopeOf(agent))\n      installed.set(agent, release)\n      all.add(release)\n      return true\n    },\n    isEnabled(agent) {\n      return !closed && installed.has(agent)\n    },\n    dispose() {\n      closed = true\n      for (const release of all) release()\n      all.clear()\n    },\n  }\n}\n"
    },
    {
      "path": "packages/plugin-daily-log/src/agent/tool-dispatcher.ts",
      "content": "/**\n * 常驻派发器：模型唯一的按需发现入口（本插件其余 15 个工具默认不注册）。\n * 描述必须接住原本散在 15 条工具描述里的「何时该用」信号（spec §5.3），\n * 因此有 220 字符硬预算。\n */\n\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { ToolDefinition } from '@deepseek-ai/dsh-tools'\nimport { DAILY_LOG_TOOL_NAMES } from './tools.ts'\nimport { DAILY_LOG_REFERENCE_TEXT } from './reference.ts'\nimport type { ToolGate } from './tool-gate.ts'\n\nexport const TOOL_DISPATCHER = 'daily_log'\n\n// 210 字符（硬预算 220）。三段式：能力 → 何时调用 → 解锁什么。\nconst DESCRIPTION =\n  'Enable the daily-log toolkit: work reports from Git commits and local agent conversations. ' +\n  'Call first for daily/weekly/monthly reports, recent-work summaries, or work statistics. ' +\n  'Unlocks all daily_log_* tools.'\n\nexport function createDailyLogDispatcher(gate: ToolGate): ToolDefinition {\n  return defineTool({\n    name: TOOL_DISPATCHER,\n    description: DESCRIPTION,\n    parameters: {},\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          enabled: { type: 'boolean', required: true },\n          message: { type: 'string', required: true },\n          tools: { type: 'array', required: true, items: { type: 'string' } },\n          // 详细引导段的唯一可靠落点：agent 作用域不提供 systemPrompt\n          // （registerDailyLogGuidance 在真机上直接短路），只有工具返回值必然进入对话。\n          guidance: { type: 'string', required: true },\n        },\n      },\n      render: (_args, value) => {\n        const result = value as { enabled: boolean; message: string; tools: string[]; guidance: string }\n        return [{ type: 'text', text: result.message + '\\n\\n' + result.guidance }]\n      },\n    },\n    execute: async (_args, exec) => {\n      const agent = exec.agent\n      if (agent === undefined) {\n        return {\n          enabled: false,\n          message: 'Cannot determine the calling session scope, so the toolkit cannot be enabled. Ask the user to enable it (/report does that when the command is registered).',\n          tools: [],\n          guidance: DAILY_LOG_REFERENCE_TEXT,\n        }\n      }\n      try {\n        const fresh = gate.enable(agent)\n        return {\n          enabled: true,\n          message: fresh\n            ? 'Daily-log toolkit enabled for this session.'\n            : 'Daily-log toolkit already enabled.',\n          tools: [...DAILY_LOG_TOOL_NAMES],\n          guidance: DAILY_LOG_REFERENCE_TEXT,\n        }\n      } catch (error) {\n        return {\n          enabled: false,\n          message: 'Failed to enable the daily-log toolkit: ' + String(error) + '. Ask the user to enable it (/report does that when the command is registered).',\n          tools: [],\n          guidance: DAILY_LOG_REFERENCE_TEXT,\n        }\n      }\n    },\n  })\n}\n"
    },
    {
      "path": "packages/plugin-daily-log/src/agent/scan-render.ts",
      "content": "/**\n * 扫描结果分层渲染。\n *\n * 问题：会话渠道逐条产出（实测 hake_app_2.0 一周 365 条），全量渲染必然撑爆上下文；\n * 而\"截断前 N 条\"会让后半段静默消失，写报告时误判为\"没干活\"。\n * 口径：行数 ∝ 分组数（会话 / 分支），与消息条数无关 —— 默认 index 只给索引，\n * summary 补每条分组的\"首问 + 末答\"，raw 才是逐条明细。\n * 折叠必须显式：被省略的分组要列出名称与条数，绝不静默丢弃。\n */\n\nimport type { ActivityEntry } from '../types.ts'\n\nexport type ScanLevel = 'index' | 'summary' | 'raw'\n\nexport interface RenderScanOptions {\n  readonly level?: ScanLevel\n  /** 总行数上限；缺省按 level 取值（index 60 / summary 160 / raw 120）。 */\n  readonly maxLines?: number\n  /** 每块最多展开的分组数；缺省按 level 取值（index 10 / summary 6）。 */\n  readonly maxGroups?: number\n  /** summary 中每条结论的截断字数（默认 400）。 */\n  readonly bodyChars?: number\n}\n\n/** 下钻过滤：会话 id（前缀包含匹配）与关键词（任一命中）。 */\nexport interface ScanFilter {\n  readonly sessionId?: string\n  readonly keywords?: string\n}\n\nconst DEFAULT_MAX_LINES: Record<ScanLevel, number> = { index: 60, summary: 160, raw: 120 }\nconst DEFAULT_MAX_GROUPS: Record<ScanLevel, number> = { index: 10, summary: 6, raw: 200 }\nconst SUMMARY_BODY_CHARS = 400\nconst QUESTION_CHARS = 200\n\nconst day = (ts: number): string => (ts > 0 ? new Date(ts).toISOString().slice(0, 10) : '?')\n\nfunction spanOf(entries: readonly ActivityEntry[]): string {\n  const times = entries.map((e) => e.ts).filter((t) => t > 0)\n  if (times.length === 0) return '?'\n  const first = day(Math.min(...times))\n  const last = day(Math.max(...times))\n  return first === last ? first : first + '~' + last\n}\n\ninterface Group {\n  readonly id: string\n  readonly title: string\n  readonly kind: 'commit' | 'conversation'\n  readonly entries: ActivityEntry[]\n}\n\ninterface Block {\n  readonly channel: string\n  readonly label: string\n  readonly entries: ActivityEntry[]\n}\n\nfunction blocksOf(entries: readonly ActivityEntry[]): Block[] {\n  const map = new Map<string, Block>()\n  for (const e of entries) {\n    const channel = e.channel ?? (e.kind === 'commit' ? 'git' : 'conversation')\n    const key = channel + '\\u0000' + e.sourceLabel\n    const hit = map.get(key)\n    if (hit) hit.entries.push(e)\n    else map.set(key, { channel, label: e.sourceLabel, entries: [e] })\n  }\n  return [...map.values()].sort((a, b) => b.entries.length - a.entries.length)\n}\n\n/** 按分组键聚合（会话 id / 分支名）；无分组键的条目各自成组。 */\nfunction groupsOf(entries: readonly ActivityEntry[]): Group[] {\n  const map = new Map<string, Group>()\n  let anon = 0\n  for (const e of entries) {\n    const id = e.group ?? '#' + String(++anon)\n    const hit = map.get(id)\n    if (hit) hit.entries.push(e)\n    else map.set(id, { id, title: e.group ?? e.title, kind: e.kind, entries: [e] })\n  }\n  for (const g of map.values()) {\n    const named = g.entries.find((e) => e.groupTitle !== undefined)\n    if (named?.groupTitle) {\n      ;(g as { title: string }).title = named.groupTitle\n    }\n    // 弱标题兜底：会话标题可能是空壳（'11'）或干脆是会话 id（'agent-abe2c29643c8ed30e'），\n    // 这类标题在报告里毫无信息量，改用该组首条用户提问。\n    if (isWeakTitle(g.title)) {\n      const q = firstUserBody(g)\n      if (q) (g as { title: string }).title = q\n    }\n  }\n  return [...map.values()].sort((a, b) => b.entries.length - a.entries.length)\n}\n\nfunction countText(g: Group): string {\n  const users = g.entries.filter((e) => e.role === 'user').length\n  const assistants = g.entries.filter((e) => e.role === 'assistant').length\n  if (g.kind === 'commit') return g.entries.length + ' 提交'\n  if (users === 0 && assistants === 0) return g.entries.length + ' 条'\n  return g.entries.length + ' 条（问 ' + users + ' / 答 ' + assistants + '）'\n}\n\n/** 会话 id 形态（'agent-abe2c29643c8ed30e'、uuid 等）：没有语义，不该出现在报告里。 */\nconst ID_LIKE = /^(agent|session|sess|run|rollout)?[0-9a-f]{8,}$/i\n\n/** 标题是否\"无信息量\"：空壳（'11'）或干脆是会话 id。 */\nfunction isWeakTitle(title: string): boolean {\n  const s = title.trim()\n  if (s.length === 0) return true\n  if (s.replace(/[^\\w\\u4e00-\\u9fa5]/g, '').length < 4) return true\n  return !/[\\u4e00-\\u9fa5]/.test(s) && ID_LIKE.test(s.replace(/[\\s_-]/g, ''))\n}\n\n/** 弱标题兜底：该组最早的一条用户提问（截 40 字）。 */\nfunction firstUserBody(g: Group): string | undefined {\n  if (g.kind !== 'conversation') return undefined\n  const hit = g.entries.filter((e) => e.role === 'user').sort((a, b) => a.ts - b.ts)[0]\n  return hit ? truncate(hit.body, 40) : undefined\n}\n\nfunction truncate(text: string, max: number): string {\n  const flat = text.replace(/\\s+/g, ' ').trim()\n  return flat.length > max ? flat.slice(0, max) + '…' : flat\n}\n\nfunction firstUser(g: Group): string | undefined {\n  const hit = g.entries.filter((e) => e.role === 'user').sort((a, b) => a.ts - b.ts)[0]\n  return hit ? truncate(hit.body, QUESTION_CHARS) : undefined\n}\n\nfunction lastAssistant(g: Group): string | undefined {\n  const hit = g.entries.filter((e) => e.role === 'assistant').sort((a, b) => b.ts - a.ts)[0]\n  return hit ? truncate(hit.body, SUMMARY_BODY_CHARS) : undefined\n}\n\nconst rawLine = (e: ActivityEntry): string =>\n  '- [' + e.kind + '] ' + e.sourceLabel + ' · ' + day(e.ts) + ' · ' + e.title\n\n/** 渲染扫描结果（纯函数，供工具与单测共用）。 */\nexport function renderScan(entries: readonly ActivityEntry[], options: RenderScanOptions = {}): string {\n  const level = options.level ?? 'index'\n  if (entries.length === 0) return '(no entries)'\n  if (level === 'raw') return renderRaw(entries, options)\n  const maxLines = options.maxLines ?? DEFAULT_MAX_LINES[level]\n  const maxGroups = options.maxGroups ?? DEFAULT_MAX_GROUPS[level]\n  const lines: string[] = []\n  const folded: string[] = []\n  for (const block of blocksOf(entries)) {\n    const groups = groupsOf(block.entries)\n    const summary = block.entries.reduce(\n      (acc, e) => (e.kind === 'commit' ? { commits: acc.commits + 1, messages: acc.messages } : { commits: acc.commits, messages: acc.messages + 1 }),\n      { commits: 0, messages: 0 },\n    )\n    const counts = [summary.commits > 0 ? summary.commits + ' 提交' : '', summary.messages > 0 ? summary.messages + ' 条消息' : ''].filter(Boolean).join(' / ')\n    lines.push('[' + block.channel + '] ' + block.label + ' · ' + spanOf(block.entries) + ' · ' + counts + ' · ' + groups.length + ' 组')\n    for (const g of groups.slice(0, maxGroups)) {\n      if (level === 'summary') {\n        lines.push('  ▸ ' + g.title + ' · ' + spanOf(g.entries) + ' · ' + countText(g))\n        const q = firstUser(g)\n        const a = lastAssistant(g)\n        if (q) lines.push('    问：' + q)\n        if (a) lines.push('    答：' + a)\n      } else {\n        lines.push('  · ' + g.title + ' · ' + spanOf(g.entries) + ' · ' + countText(g))\n      }\n    }\n    if (groups.length > maxGroups) {\n      const rest = groups.slice(maxGroups)\n      folded.push(block.channel + '/' + block.label + ' ' + rest.length + ' 组（' + rest.slice(0, 3).map((g) => g.title).join('、') + (rest.length > 3 ? ' 等' : '') + '）')\n    }\n  }\n  let truncatedLines = 0\n  if (lines.length > maxLines) {\n    truncatedLines = lines.length - maxLines\n    lines.length = maxLines\n  }\n  const footer: string[] = []\n  if (folded.length > 0) footer.push('… 未展开分组：' + folded.join('；'))\n  if (truncatedLines > 0) footer.push('… 另有 ' + truncatedLines + ' 行未显示')\n  const total = entries.reduce((n, _e) => n + 1, 0)\n  footer.push('（共 ' + total + ' 条 · ' + blocksOf(entries).reduce((n, b) => n + groupsOf(b.entries).length, 0) + ' 组；下钻：level=summary，或 level=raw + session_id / keywords）')\n  return lines.concat(footer).join('\\n')\n}\n\nfunction renderRaw(entries: readonly ActivityEntry[], options: RenderScanOptions): string {\n  const maxLines = options.maxLines ?? DEFAULT_MAX_LINES.raw\n  const sorted = [...entries].sort((a, b) => a.ts - b.ts)\n  const lines = sorted.slice(0, maxLines).map(rawLine)\n  if (sorted.length > maxLines) {\n    lines.push('… (truncated, ' + (sorted.length - maxLines) + ' more)')\n  }\n  return lines.join('\\n')\n}\n\n/** 应用下钻过滤（会话 id 包含匹配；keywords 空格/逗号分隔，任一命中）。 */\nexport function filterEntries(entries: readonly ActivityEntry[], filter: ScanFilter = {}): ActivityEntry[] {\n  const session = filter.sessionId?.trim().toLowerCase()\n  const terms = (filter.keywords ?? '')\n    .split(/[\\s,，]+/)\n    .map((t) => t.trim().toLowerCase())\n    .filter(Boolean)\n  return entries.filter((e) => {\n    if (session) {\n      const key = ((e.group ?? '') + ' ' + (e.groupTitle ?? '')).toLowerCase()\n      if (!key.includes(session)) return false\n    }\n    if (terms.length > 0) {\n      const hay = (e.title + ' ' + e.body).toLowerCase()\n      if (!terms.some((t) => hay.includes(t))) return false\n    }\n    return true\n  })\n}\n"
    },
    {
      "path": "packages/plugin-daily-log/src/agent/tools.ts",
      "content": "/**\n * plugin-daily-log × agent harness 桥（host 侧）—— 数据源/扫描/报告/模板工具注册。\n *\n * 把 ctx.dailyLog（DailyLogService，同 ctx 直调）暴露成 agent 工具：\n * - 读工具（list_sources / scan / list_reports / get_report / list_templates / get_template /\n *   prepare_report）放行；\n * - 写工具（add_source / save_report / export_report / delete_report / template_*）在宿主有\n *   approval seam 且会话有效策略为 ask（会真正弹确认）时经 tools/pre-execute 弹确认；\n *   无 seam、策略为 never（禁弹窗，ask 会被 ApprovalService 确定性拒绝）时放行 ——\n *   判定见 dailyLogWriteShouldAsk；\n * - guard（单调拒绝）：内置模板不可修改/删除（service 已兜底，此处提前拒绝）。\n *\n * 全局只注册 guard、tools/pre-execute 钩子与恒驻的 daily_log 派发器；15 个 daily_log_*\n * 工具本身经 ToolGate 按 agent 按需注入（详见 index.ts 的 createDailyLogGate）。\n * 工具以 tools 服务判存后条件挂载（ctx.inject），纯 UI 宿主照常工作（不注册工具）。\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type {} from '@deepseek-ai/dsh-user-approval'\nimport type { ToolDefinition } from '@deepseek-ai/dsh-tools'\nimport type { DailyLogService } from '../service.ts'\nimport { SOURCE_KINDS } from '../types.ts'\nimport type { ActivityEntry, ReportId, SourceId, TemplateId } from '../types.ts'\nimport { filterEntries, renderScan } from './scan-render.ts'\nimport type { ScanLevel } from './scan-render.ts'\nimport { createDailyLogDispatcher } from './tool-dispatcher.ts'\nimport type { ToolGate } from './tool-gate.ts'\n\nexport const DAILY_LOG_TOOL_PREFIX = 'daily_log_'\n\nconst TOOL_LIST_SOURCES = DAILY_LOG_TOOL_PREFIX + 'list_sources'\nconst TOOL_SCAN = DAILY_LOG_TOOL_PREFIX + 'scan'\nconst TOOL_LIST_REPORTS = DAILY_LOG_TOOL_PREFIX + 'list_reports'\nconst TOOL_GET_REPORT = DAILY_LOG_TOOL_PREFIX + 'get_report'\nconst TOOL_LIST_TEMPLATES = DAILY_LOG_TOOL_PREFIX + 'list_templates'\nconst TOOL_GET_TEMPLATE = DAILY_LOG_TOOL_PREFIX + 'get_template'\nconst TOOL_ADD_SOURCE = DAILY_LOG_TOOL_PREFIX + 'add_source'\nconst TOOL_PREPARE = DAILY_LOG_TOOL_PREFIX + 'prepare_report'\nconst TOOL_SAVE = DAILY_LOG_TOOL_PREFIX + 'save_report'\nconst TOOL_EXPORT = DAILY_LOG_TOOL_PREFIX + 'export_report'\nconst TOOL_DELETE_REPORT = DAILY_LOG_TOOL_PREFIX + 'delete_report'\nconst TOOL_TEMPLATE_CREATE = DAILY_LOG_TOOL_PREFIX + 'template_create'\nconst TOOL_TEMPLATE_UPDATE = DAILY_LOG_TOOL_PREFIX + 'template_update'\nconst TOOL_TEMPLATE_DELETE = DAILY_LOG_TOOL_PREFIX + 'template_delete'\nconst TOOL_TEMPLATE_SET_DEFAULT = DAILY_LOG_TOOL_PREFIX + 'set_default_template'\n\nexport function isDailyLogTool(name: string): boolean {\n  return name.startsWith(DAILY_LOG_TOOL_PREFIX)\n}\n\nconst WRITE_TOOLS = new Set<string>([\n  TOOL_ADD_SOURCE, TOOL_SAVE, TOOL_EXPORT, TOOL_DELETE_REPORT,\n  TOOL_TEMPLATE_CREATE, TOOL_TEMPLATE_UPDATE, TOOL_TEMPLATE_DELETE, TOOL_TEMPLATE_SET_DEFAULT,\n])\n\nfunction describeAction(tool: string): string {\n  switch (tool) {\n    case TOOL_ADD_SOURCE: return 'add a data source'\n    case TOOL_SAVE: return 'save a generated report'\n    case TOOL_EXPORT: return 'export a report to a markdown file'\n    case TOOL_DELETE_REPORT: return 'delete a report'\n    case TOOL_TEMPLATE_CREATE: return 'create a template'\n    case TOOL_TEMPLATE_UPDATE: return 'update a template'\n    case TOOL_TEMPLATE_DELETE: return 'delete a template'\n    case TOOL_TEMPLATE_SET_DEFAULT: return 'change the default template'\n    default: return 'write'\n  }\n}\n\n/** 'ask' | 'never' —— 与 @deepseek-ai/dsh-user-approval 的 ApprovalPolicy 同形。 */\ntype DailyLogApprovalPolicy = 'ask' | 'never'\n\n/**\n * pre-execute ask 门禁判定（纯函数，供单测）：\n * - policy === undefined：宿主未装配 approval（无 seam）→ 放行（保持原语义）；\n * - policy === 'never'：会话禁弹窗，ApprovalService 对一切 ask 确定性返回\n *   'rejected'（decide 在分发应答器之前直接拒绝）→ 弹确认只会让用户已在对话中\n *   确认的写操作被自动拒绝，等同「无交互通道」，放行；\n * - policy === 'ask'：宿主会真正弹确认 → 写工具先 ask。\n */\nexport function dailyLogWriteShouldAsk(policy: DailyLogApprovalPolicy | undefined): boolean {\n  return policy === 'ask'\n}\n\n/** 扫描工具描述里对 level 的说明（与 scan-render 的口径一致）。 */\nconst SCAN_LEVEL_HINT =\n  'level=index (default) lists one row per session/branch group, so rows track groups rather than messages; ' +\n  'level=summary adds each group first question and last answer; level=raw lists every entry. ' +\n  'Collapsed groups are always listed with names and counts, never silently dropped.'\n\n/** 15 个工具的名字（顺序与注册顺序一致）。 */\nexport const DAILY_LOG_TOOL_NAMES: readonly string[] = [\n  TOOL_LIST_SOURCES, TOOL_SCAN, TOOL_LIST_REPORTS, TOOL_GET_REPORT, TOOL_LIST_TEMPLATES,\n  TOOL_GET_TEMPLATE, TOOL_ADD_SOURCE, TOOL_PREPARE, TOOL_SAVE, TOOL_EXPORT,\n  TOOL_DELETE_REPORT, TOOL_TEMPLATE_CREATE, TOOL_TEMPLATE_UPDATE, TOOL_TEMPLATE_DELETE,\n  TOOL_TEMPLATE_SET_DEFAULT,\n]\n\n/**\n * 构造全部 daily_log_* 工具定义，交给 register 决定注册到哪个 scope。\n * 定义期只闭包 svc，不调用它 —— 因此可在 gate 里按 agent 生成新的一组。\n */\nexport function buildDailyLogTools(\n  svc: DailyLogService,\n  register: (definition: ToolDefinition) => void,\n): void {\n  /* ----- 读工具 ----- */\n\n  register(defineTool({\n    name: TOOL_LIST_SOURCES,\n    description: 'List daily-log projects (one project = one unique directory path; git / DSH / Claude / Codex channels aggregate per project). Returns id, type, label, path.',\n    parameters: {},\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          sources: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              properties: {\n                id: { type: 'string', required: true },\n                type: { type: 'string', required: true, enum: ['code', 'other'] },\n                label: { type: 'string', required: true },\n                path: { type: 'string', required: true },\n              },\n            },\n          },\n        },\n      },\n      render: (_args, value) => {\n        const list = (value as { sources: Array<{ id: string; type: string; label: string; path: string }> }).sources\n        if (list.length === 0) return [{ type: 'text', text: '(no projects)' }]\n        return [{ type: 'text', text: list.map((s) => '- ' + s.id + ' · [' + s.type + '] ' + s.label + ' (' + s.path + ')').join('\\n') }]\n      },\n    },\n    async execute() {\n      const all = await svc.listSources()\n      return { sources: all.map((s) => ({ id: s.id, type: s.type, label: s.label, path: s.path })) }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_SCAN,\n    description: 'Scan data sources for activity entries (git commits / conversation turns) within a date range. '\n      + 'Omit source_id to scan all sources; returns the entries plus a count. '\n      + SCAN_LEVEL_HINT,\n    parameters: {\n      source_id: { type: 'string', description: 'Optional source id; omit to scan all sources.' },\n      since: { type: 'string', required: true, description: 'Start date, e.g. \"2026-06-30\" or \"Monday\".' },\n      until: { type: 'string', description: 'Optional end date, e.g. \"2026-07-05\".' },\n      level: {\n        type: 'string',\n        enum: ['index', 'summary', 'raw'],\n        description: 'Rendering level (default index): index=per-session/branch overview, summary=index + first question & last answer per group, raw=every entry.',\n      },\n      session_id: { type: 'string', description: 'Drill-down: only entries of sessions/branches whose id or title contains this string.' },\n      keywords: { type: 'string', description: 'Drill-down: only entries whose text contains any of these space/comma separated terms.' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          entries: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              properties: {\n                ts: { type: 'number', required: true },\n                sourceLabel: { type: 'string', required: true },\n                channel: { type: 'string', enum: SOURCE_KINDS },\n                kind: { type: 'string', required: true, enum: ['commit', 'conversation'] },\n                title: { type: 'string', required: true },\n                body: { type: 'string', required: true },\n                group: { type: 'string' },\n                groupTitle: { type: 'string' },\n                role: { type: 'string', enum: ['user', 'assistant'] },\n              },\n            },\n          },\n          count: { type: 'number', required: true },\n        },\n      },\n      render: (args, value) =>\n        [{ type: 'text', text: renderScan((value as { entries: ActivityEntry[] }).entries, { level: args.level as ScanLevel | undefined }) }],\n    },\n    async execute(args) {\n      const since = args.since as string\n      const until = args.until as string | undefined\n      const range = { since, ...(until ? { until } : {}) }\n      const list = await svc.listSources()\n      const targets = args.source_id !== undefined\n        ? list.filter((s) => s.id === (args.source_id as SourceId))\n        : list\n      const entries: ActivityEntry[] = []\n      for (const s of targets) {\n        const r = await svc.scanSource(s.id, range)\n        entries.push(...r.entries)\n      }\n      // 下钻过滤在渲染与结构化返回上同时生效，避免显示与取值不一致。\n      const filtered = filterEntries(entries, {\n        ...(args.session_id !== undefined ? { sessionId: args.session_id as string } : {}),\n        ...(args.keywords !== undefined ? { keywords: args.keywords as string } : {}),\n      })\n      return { entries: filtered, count: filtered.length }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_LIST_REPORTS,\n    description: 'List generated daily-log reports; returns id, title, dateRange and createdAt per report.',\n    parameters: {},\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          reports: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              properties: {\n                id: { type: 'string', required: true },\n                title: { type: 'string', required: true },\n                dateRange: {\n                  type: 'object',\n                  additionalProperties: false,\n                  properties: {\n                    since: { type: 'string', required: true },\n                    until: { type: 'string' },\n                  },\n                },\n                createdAt: { type: 'number', required: true },\n              },\n            },\n          },\n        },\n      },\n      render: (_args, value) => {\n        const list = (value as { reports: Array<{ id: string; title: string; createdAt: number }> }).reports\n        if (list.length === 0) return [{ type: 'text', text: '(no reports)' }]\n        return [{ type: 'text', text: list.map((r) => '- ' + r.id + ' · ' + r.title).join('\\n') }]\n      },\n    },\n    async execute() {\n      return { reports: svc.listReports().map((r) => ({ id: r.id, title: r.title, dateRange: r.dateRange, createdAt: r.createdAt })) }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_GET_REPORT,\n    description: 'Read one generated report by id; returns its title and full markdown body.',\n    parameters: { report_id: { type: 'string', required: true, description: 'The report id from daily_log_list_reports.' } },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { title: { type: 'string', required: true }, markdown: { type: 'string', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: (value as { markdown: string }).markdown }],\n    },\n    async execute(args) {\n      const r = svc.getReport(args.report_id as ReportId)\n      if (!r) throw new Error('report ' + args.report_id + ' not found')\n      return { title: r.title, markdown: r.markdown }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_LIST_TEMPLATES,\n    description: 'List report templates; returns id, name, isBuiltin and isDefault per template. The default template is used when daily_log_prepare_report omits template_id.',\n    parameters: {},\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          templates: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              properties: {\n                id: { type: 'string', required: true },\n                name: { type: 'string', required: true },\n                isBuiltin: { type: 'boolean', required: true },\n                isDefault: { type: 'boolean', required: true },\n              },\n            },\n          },\n        },\n      },\n      render: (_args, value) => {\n        const list = (value as { templates: Array<{ id: string; name: string; isBuiltin: boolean; isDefault: boolean }> }).templates\n        return [{ type: 'text', text: list.map((t) => '- ' + t.id + ' · ' + t.name + (t.isBuiltin ? ' (builtin)' : '') + (t.isDefault ? ' (default)' : '')).join('\\n') }]\n      },\n    },\n    async execute() {\n      return { templates: svc.listTemplates().map((t) => ({ id: t.id, name: t.name, isBuiltin: t.isBuiltin, isDefault: t.isDefault })) }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_GET_TEMPLATE,\n    description: 'Read one report template by id; returns its name and full markdown content.',\n    parameters: { template_id: { type: 'string', required: true, description: 'The template id from daily_log_list_templates.' } },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { name: { type: 'string', required: true }, content: { type: 'string', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: (value as { content: string }).content }],\n    },\n    async execute(args) {\n      const t = svc.getTemplate(args.template_id as TemplateId)\n      if (!t) throw new Error('template ' + args.template_id + ' not found')\n      return { name: t.name, content: t.content }\n    },\n  }))\n\n  /* ----- 写工具 ----- */\n\n  register(defineTool({\n    name: TOOL_ADD_SOURCE,\n    description: 'Add a project: one unique directory path (a git repo or any project directory). All channels that hit the path (git commits / DSH / Claude / Codex sessions) aggregate at scan time. Returns the new source id, label and type.',\n    parameters: {\n      path: { type: 'string', required: true, description: 'Absolute path of the project directory.' },\n      label: { type: 'string', description: 'Optional display label.' },\n      author: { type: 'string', description: 'Optional git author filter (git commits only). Defaults to the repo user.email (own commits only); pass \"*\" for all authors.' },\n      type: { type: 'string', enum: ['code', 'other'], description: 'Optional project type; auto-detected when omitted (has .git → code).' },\n    },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { id: { type: 'string', required: true }, label: { type: 'string', required: true }, type: { type: 'string', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: 'added project ' + (value as { id: string }).id }],\n    },\n    async execute(args) {\n      const s = await svc.addSource({\n        path: args.path as string,\n        ...(args.label !== undefined ? { label: args.label as string } : {}),\n        ...(args.author !== undefined ? { author: args.author as string } : {}),\n        ...(args.type !== undefined ? { type: args.type as 'code' | 'other' } : {}),\n      })\n      return { id: s.id, label: s.label, type: s.type }\n    },\n  }))\n\n  /* prepare_report：进入生成阶段，返回模板引导（只读，不扫描） */\n\n  register(defineTool({\n    name: TOOL_PREPARE,\n    description: 'Enter the generation phase: resolves the selected template guidance (instruction section + skeleton section) and the source count without scanning again. Returns templateName, skeletonSection and sourceCount; write the report body yourself following that skeleton.',\n    parameters: {\n      reportType: { type: 'string', required: true, description: 'Report type label, e.g. 日报 / 周报 / 月报.' },\n      since: { type: 'string', required: true, description: 'Start date, e.g. \"2026-06-30\".' },\n      until: { type: 'string', description: 'Optional end date.' },\n      source_ids: { type: 'array', items: { type: 'string' }, description: 'Optional source ids; omit to use all sources.' },\n      template_id: { type: 'string', description: 'Optional template id; omit to use the default template.' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          templateName: { type: 'string', required: true },\n          skeletonSection: { type: 'string', required: true },\n          sourceCount: { type: 'number', required: true },\n        },\n      },\n      render: (_args, value) => {\n        const v = value as { templateName: string; skeletonSection: string; sourceCount: number }\n        return [{ type: 'text', text: 'template: ' + v.templateName + ' (sources: ' + v.sourceCount + ')\\n\\n骨架：\\n' + v.skeletonSection.slice(0, 600) }]\n      },\n    },\n    async execute(args) {\n      const r = await svc.prepareReport({\n        reportType: args.reportType as string,\n        dateRange: { since: args.since as string, ...(args.until !== undefined ? { until: args.until as string } : {}) },\n        ...(args.source_ids !== undefined ? { sourceIds: args.source_ids as SourceId[] } : {}),\n        ...(args.template_id !== undefined ? { templateId: args.template_id as TemplateId } : {}),\n      })\n      return { templateName: r.template.name, skeletonSection: r.template.skeletonSection, sourceCount: r.sourceCount }\n    },\n  }))\n\n  /* save_report：把 LLM 撰写的正文落 reports 表（写，ask） */\n\n  register(defineTool({\n    name: TOOL_SAVE,\n    description: 'Save a report the model authored (full markdown body) into the reports table. Only call after the user has confirmed the report shown in chat. Returns the new report id and title.',\n    parameters: {\n      markdown: { type: 'string', required: true, description: 'The full markdown body the model wrote.' },\n      title: { type: 'string', description: 'Optional report title; defaults to reportType + date range.' },\n      reportType: { type: 'string', description: 'Report type label (stored on the record), e.g. 周报.' },\n      since: { type: 'string', required: true, description: 'Start date, e.g. \"2026-06-30\".' },\n      until: { type: 'string', description: 'Optional end date.' },\n      source_ids: { type: 'array', items: { type: 'string' }, required: true, description: 'Source ids the report covers.' },\n      template_id: { type: 'string', description: 'Optional template id used for generation.' },\n    },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { id: { type: 'string', required: true }, title: { type: 'string', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: 'saved report ' + (value as { id: string }).id }],\n    },\n    async execute(args) {\n      const r = await svc.saveReport({\n        markdown: args.markdown as string,\n        ...(args.title !== undefined ? { title: args.title as string } : {}),\n        ...(args.reportType !== undefined ? { reportType: args.reportType as string } : {}),\n        dateRange: { since: args.since as string, ...(args.until !== undefined ? { until: args.until as string } : {}) },\n        sourceIds: (args.source_ids as SourceId[]) ?? [],\n        ...(args.template_id !== undefined ? { templateId: args.template_id as TemplateId } : {}),\n      })\n      return { id: r.id, title: r.title }\n    },\n  }))\n\n  /* export_report：把已存报告导出为 .md（写，ask） */\n\n  register(defineTool({\n    name: TOOL_EXPORT,\n    description: 'Export an existing report (report_id from daily_log_list_reports) to a markdown file under the configured output directory, or ~/daily-log-reports if none is set. Returns the written path.',\n    parameters: {\n      report_id: { type: 'string', required: true, description: 'The report id.' },\n      output_dir: { type: 'string', description: 'Optional output directory; defaults to the configured one or ~/daily-log-reports.' },\n    },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { path: { type: 'string', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: 'exported to ' + (value as { path: string }).path }],\n    },\n    async execute(args) {\n      const path = await svc.exportReport(args.report_id as ReportId, args.output_dir !== undefined ? (args.output_dir as string) : undefined)\n      return { path }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_DELETE_REPORT,\n    description: 'Delete one report by id; returns whether a report was deleted.',\n    parameters: { report_id: { type: 'string', required: true, description: 'The report id from daily_log_list_reports.' } },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { deleted: { type: 'boolean', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: value.deleted ? 'deleted' : 'not found' }],\n    },\n    async execute(args) {\n      return { deleted: await svc.deleteReport(args.report_id as ReportId) }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_TEMPLATE_CREATE,\n    description: 'Create a report template: Markdown with an optional instruction section, the DATA marker (<!-- DATA -->), and a required skeleton section guiding the generation phase (no mustache placeholders). Returns the new template id and name.',\n    parameters: {\n      name: { type: 'string', required: true, description: 'Template name.' },\n      content: { type: 'string', required: true, description: 'Template content: optional instruction section above <!-- DATA --> and required skeleton section below it, guiding the LLM as it writes the report body (no mustache placeholders).' },\n    },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { id: { type: 'string', required: true }, name: { type: 'string', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: 'created template ' + (value as { id: string }).id }],\n    },\n    async execute(args) {\n      const t = await svc.createTemplate({ name: args.name as string, content: args.content as string })\n      return { id: t.id, name: t.name }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_TEMPLATE_UPDATE,\n    description: 'Update the name and/or content of a template by id; returns the updated template id and name.',\n    parameters: {\n      template_id: { type: 'string', required: true, description: 'The template id from daily_log_list_templates.' },\n      name: { type: 'string', description: 'New name.' },\n      content: { type: 'string', description: 'New content.' },\n    },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { id: { type: 'string', required: true }, name: { type: 'string', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: 'updated template ' + (value as { id: string }).id }],\n    },\n    async execute(args) {\n      const t = await svc.updateTemplate(args.template_id as TemplateId, {\n        ...(args.name !== undefined ? { name: args.name as string } : {}),\n        ...(args.content !== undefined ? { content: args.content as string } : {}),\n      })\n      if (!t) throw new Error('template ' + args.template_id + ' not found')\n      return { id: t.id, name: t.name }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_TEMPLATE_DELETE,\n    description: 'Delete a template by id; returns whether a template was deleted. The builtin default template cannot be deleted.',\n    parameters: { template_id: { type: 'string', required: true, description: 'The template id from daily_log_list_templates.' } },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { deleted: { type: 'boolean', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: value.deleted ? 'deleted' : 'not found' }],\n    },\n    async execute(args) {\n      return { deleted: await svc.deleteTemplate(args.template_id as TemplateId) }\n    },\n  }))\n\n  register(defineTool({\n    name: TOOL_TEMPLATE_SET_DEFAULT,\n    description: 'Set a template as the default (the one used when daily_log_prepare_report omits template_id); returns whether the template existed.',\n    parameters: { template_id: { type: 'string', required: true, description: 'The template id from daily_log_list_templates.' } },\n    output: {\n      schema: { type: 'object', additionalProperties: false, properties: { ok: { type: 'boolean', required: true } } },\n      render: (_args, value) => [{ type: 'text', text: value.ok ? 'set' : 'not found' }],\n    },\n    async execute(args) {\n      return { ok: await svc.setDefaultTemplate(args.template_id as TemplateId) }\n    },\n  }))\n}\n\n/**\n * 全局只装 guard + tools/pre-execute 钩子，以及恒注册的派发器；\n * 15 个 daily_log_* 工具与详细引导段改由 ToolGate 按 agent 按需注入\n * （见 index.ts 的 createDailyLogGate），不再出现在全局 scope。\n */\nexport function installDailyLogTools(ctx: Context, gate: ToolGate): void {\n  const svc = ctx.dailyLog\n\n  // guard（单调拒绝）：内置模板不可修改/删除（service 已兜底，此处提前拒绝）。\n  ctx.tools.guard((exec) => {\n    if (exec.name !== TOOL_TEMPLATE_DELETE && exec.name !== TOOL_TEMPLATE_UPDATE) return undefined\n    const args = exec.arguments as { template_id?: unknown } | undefined\n    const id = args?.template_id\n    if (typeof id !== 'string') return undefined\n    const t = svc.listTemplates().find((x) => x.id === id)\n    if (t?.isBuiltin) return 'template ' + id + ' is the builtin default and cannot be modified or deleted'\n    return undefined\n  })\n\n  // pre-execute ask：宿主有 approval seam 且会话有效策略为 ask（会真正弹确认）时，\n  // 写工具先弹确认；策略 never（禁弹窗 → ApprovalService 确定性拒绝一切 ask）或\n  // 无 agent 可路由时放行 —— 避免用户已在对话中确认的操作仍被自动拒绝。\n  ctx.on('tools/pre-execute', async (exec, next) => {\n    if (!isDailyLogTool(exec.name)) return next()\n    if (!WRITE_TOOLS.has(exec.name)) return next()\n    const approval = ctx.get('approval')\n    if (approval === undefined) return next()\n    const policy = exec.agent === undefined\n      ? undefined\n      : approval.overrideOf(exec.agent.session) ?? approval.config.policy ?? 'ask'\n    if (!dailyLogWriteShouldAsk(policy)) return next()\n    return { kind: 'ask', reason: 'The agent wants to ' + describeAction(exec.name) + ' in daily-log.' }\n  })\n\n  // 派发器恒注册：模型唯一的按需发现入口（其余 15 个工具默认不注册）。\n  ctx.tools.register(createDailyLogDispatcher(gate))\n}\n"
